SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) = 1965 AND d.icd_code IN ('250.0', '250.1', '250.9', '251.0', '251.1', '251.9', '252.0', '252.1', '252.9', '253.0', '253.1', '253.9', '254.0', '254.1', '254.9', '255.0', '255.1', '255.9', '256.0', '256.1', '256.9', '257.0', '257.1', '257.9', '258.0', '258.1', '258.9', '259.0', '259.1', '259.9') AND (e.charttime BETWEEN a.intime AND a.outtime OR e.charttime BETWEEN b.intime AND b.outtime OR e.charttime BETWEEN c.intime AND c.outtime OR e.charttime BETWEEN d.intime AND d.outtime) THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id LEFT JOIN transfers t ON a.subject_id = t.subject_id AND a.hadm_id = t.hadm_id LEFT JOIN (SELECT subject_id, MIN(charttime) AS intime, MAX(charttime) AS outtime FROM chartevents GROUP BY subject_id) e ON a.subject_id = e.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM p.dob) = 1965 AND d.icd_code IN ('250.0', '250.1', '250.9', '251.0', '251.1', '251.9', '252.0', '252.1', '252.9', '253.0', '253.1', '253.9', '254.0', '254.1', '254.9', '255.0', '255.1', '255.9', '256.0', '256.1', '256.9', '257.0', '257.1', '257.9', '258.0', '258.1', '258.9', '259.0', '259.1', '259.9') AND (e.charttime BETWEEN a.intime AND a.outtime OR e.charttime BETWEEN b.intime AND b.outtime OR e.charttime BETWEEN c.intime AND c.outtime OR e.charttime BETWEEN d.intime AND d.outtime) AND (t.intime IS NULL OR t.intime <= a.intime) AND (t.outtime IS NULL OR t.outtime >= a.outtime);